{
  "task_id": "hre_pwm_deadtime_001",
  "domain_id": "hardware_reverse_engineering",
  "title": "Recover complementary PWM with dead-time insertion",
  "description": "Reverse engineer a gate-level netlist and an obfuscated RTL wrapper describing a 4-bit-programmable complementary PWM generator with a fixed 16-clock period, used to drive a two-switch half-bridge gate driver. Submit a clean, word-level Verilog module that reproduces the exact same cycle-accurate behavior, including the safety gap inserted around every duty-cycle transition.",
  "input_artifacts": [
    "inputs/gate_netlist.v",
    "inputs/obfuscated_rtl.v",
    "inputs/design_brief.md"
  ],
  "expected_output": {
    "path": "submission/recovered_rtl.v",
    "module_name": "pwm_deadtime_gen",
    "ports": [
      { "name": "clk", "direction": "input", "width": 1, "description": "Rising-edge clock" },
      { "name": "rst", "direction": "input", "width": 1, "description": "Synchronous, active-high reset" },
      { "name": "en", "direction": "input", "width": 1, "description": "Active-high enable, sampled synchronously" },
      { "name": "duty", "direction": "input", "width": 4, "description": "Programmable duty value, 0-15" },
      { "name": "pwm_hi", "direction": "output reg", "width": 1, "description": "High-side complementary drive" },
      { "name": "pwm_lo", "direction": "output reg", "width": 1, "description": "Low-side complementary drive" }
    ],
    "notes": "Must be a single self-contained file, compilable standalone with iverilog, matching the pinned port list exactly."
  },
  "evaluation": {
    "mode": "simulate",
    "toolchain": ["iverilog", "vvp", "yosys"],
    "baselines": [
      "HAL benchmarks",
      "ISCAS'85",
      "ITC'99"
    ],
    "metrics": [
      {
        "name": "cycle_accurate_match_rate",
        "description": "Fraction of simulated clock cycles across all test vectors (duty sweep 0-15, reset sequences, enable-hold sequences) where submission pwm_hi and pwm_lo exactly match the independently generated reference design's outputs.",
        "direction": "maximize"
      },
      {
        "name": "overlap_violation_count",
        "description": "Number of clock cycles observed during simulation where pwm_hi and pwm_lo are simultaneously high; must be zero for the submission to pass regardless of other scores.",
        "direction": "minimize"
      },
      {
        "name": "deadtime_width_error",
        "description": "Sum of absolute differences between the observed dead-time gap length (in cycles) and the required 2-cycle gap, measured at both period-start and duty-boundary transitions across all tested duty values.",
        "direction": "minimize"
      },
      {
        "name": "functional_equivalence",
        "description": "Boolean pass/fail indicating whether the recovered RTL, when compiled and simulated, is behaviorally equivalent (bit-exact, cycle-exact) to the reference across the full FR1-FR4 and SR1-SR2 test suite.",
        "direction": "maximize"
      }
    ]
  },
  "submission_contract": {
    "kind": "analysis_report",
    "answer_path": "submission/recovered_rtl.v",
    "note": "Participants do not edit files under inputs/. They replace the placeholder at submission/recovered_rtl.v with their recovered design. The shipped starting file is a naive placeholder and is expected to fail evaluation."
  }
}

// ============================================================
// auto-generated by legacy synthesis flow (flatten pass 3 of 4)
// module: obf_pwm_wrapper
// source netlist: pwm_gd_block.src (archived, not recovered)
// do not hand-edit; regenerate from upstream RTL if available
// ============================================================

module obf_pwm_wrapper (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_en,
    input  wire [3:0] i_duty,
    output reg        o_hi,
    output reg        o_lo
);

    // temp net: free-running state register (flattened counter)
    reg [3:0] cnt_r;

    // temp nets: comparator taps against duty +/- small offsets
    wire stateA;   // window-open tap for hi side
    wire stateB;   // window-open tap for lo side
    wire n1, n2, n3, n4;
    wire wire_23, wire_24;

    // n1: counter above the low guard band (>=2)
    assign n1 = (cnt_r >= 4'd2);

    // n2: counter still below duty threshold
    assign n2 = (cnt_r < i_duty);

    // stateA: hi-side window candidate before dead-time exclusion
    assign stateA = n1 & n2;

    // n3: counter at least two past duty threshold (post-duty guard)
    assign n3 = (cnt_r >= (i_duty + 4'd2));

    // n4: counter has not wrapped past top of period
    assign n4 = (cnt_r <= 4'd15);

    // wire_23 / wire_24: intermediate flatten artifacts, kept for
    // structural equivalence with original synthesis netlist
    assign wire_23 = n3 & n4;
    assign wire_24 = wire_23;

    // stateB: lo-side window candidate
    assign stateB = wire_24;

    // counter update: increments while enabled, wraps mod 16
    always @(posedge i_clk) begin
        if (i_rst) begin
            cnt_r <= 4'd0;
        end else if (i_en) begin
            cnt_r <= cnt_r + 4'd1;
        end else begin
            cnt_r <= cnt_r;
        end
    end

    // output register stage: registered one cycle behind stateA/stateB,
    // consistent with downstream driver stage timing requirements
    always @(posedge i_clk) begin
        if (i_rst) begin
            o_hi <= 1'b0;
            o_lo <= 1'b0;
        end else begin
            o_hi <= stateA;
            o_lo <= stateB;
        end
    end

endmodule

// ============================================================
// gate-level netlist recovered from teardown scan
// module: gate_pwm_block
// flattened cell-level representation, generic net names
// local DFF primitive declared below for standalone elaboration
// ============================================================

module DFF (
    input  wire D,
    input  wire CLK,
    input  wire RST,
    output reg  Q
);
    always @(posedge CLK) begin
        if (RST)
            Q <= 1'b0;
        else
            Q <= D;
    end
endmodule

module gate_pwm_block (
    input  wire CLK,
    input  wire RST,
    input  wire EN,
    input  wire D0,
    input  wire D1,
    input  wire D2,
    input  wire D3,
    output wire PH,
    output wire PL
);

    // ---- counter state bits (cnt[0]=n1 ... cnt[3]=n4) ----
    wire n1, n2, n3, n4;

    // ---- ripple-carry increment logic (cnt + 1) ----
    wire w_a, w_b, w_c;
    wire c0, c1, c2;

    // bit0 toggles every enabled cycle
    xor  u_x0 (w_a, n1, 1'b1);

    // carry chain for bits 1..3
    and  u_c0 (c0, n1, 1'b1);
    xor  u_x1 (w_b, n2, c0);
    and  u_c1 (c1, n2, c0);
    xor  u_x2 (w_c, n3, c1);
    and  u_c2 (c2, n3, c1);
    xor  u_x3 (n40_next, n4, c2);

    wire n40_next;

    // ---- next-state muxing: hold when EN=0, incr when EN=1, else 0 on RST ----
    wire mux0, mux1, mux2, mux3;
    wire not_en;

    not  u_ne (not_en, EN);

    wire hold0, hold1, hold2, hold3;
    wire inc0, inc1, inc2, inc3;

    and  u_h0 (hold0, n1, not_en);
    and  u_h1 (hold1, n2, not_en);
    and  u_h2 (hold2, n3, not_en);
    and  u_h3 (hold3, n4, not_en);

    and  u_i0 (inc0, w_a, EN);
    and  u_i1 (inc1, w_b, EN);
    and  u_i2 (inc2, w_c, EN);
    and  u_i3 (inc3, n40_next, EN);

    or   u_m0 (mux0, hold0, inc0);
    or   u_m1 (mux1, hold1, inc1);
    or   u_m2 (mux2, hold2, inc2);
    or   u_m3 (mux3, hold3, inc3);

    // ---- state flip-flops ----
    DFF dff_c0 (.D(mux0), .CLK(CLK), .RST(RST), .Q(n1));
    DFF dff_c1 (.D(mux1), .CLK(CLK), .RST(RST), .Q(n2));
    DFF dff_c2 (.D(mux2), .CLK(CLK), .RST(RST), .Q(n3));
    DFF dff_c3 (.D(mux3), .CLK(CLK), .RST(RST), .Q(n4));

    // ---- guard band: counter >= 2  (n4 term unused for >=2 since 2..3 use only n2) ----
    // n5 = n2 & ~( n1 & ~n2 )  simplified: cnt>=2 means bit1 or bit2 or bit3 set,
    // equivalently NOT(cnt==0) AND NOT(cnt==1)
    wire n5, n6, n7, n8, n9;
    wire not_n1, not_n2, not_n3, not_n4;

    not  u_n1 (not_n1, n1);
    not  u_n2 (not_n2, n2);
    not  u_n3 (not_n3, n3);
    not  u_n4 (not_n4, n4);

    // cnt==0: ~n1 & ~n2 & ~n3 & ~n4
    and  u_eq0a (n6, not_n1, not_n2);
    and  u_eq0b (n7, not_n3, not_n4);
    and  u_eq0  (n8, n6, n7);

    // cnt==1: n1 & ~n2 & ~n3 & ~n4
    and  u_eq1a (n9, n1, not_n2);
    wire n10, n11;
    and  u_eq1b (n10, not_n3, not_n4);
    and  u_eq1  (n11, n9, n10);

    // guard_ge2 = NOT(cnt==0) AND NOT(cnt==1)
    wire not_eq0, not_eq1, n12;
    not  u_ne0 (not_eq0, n8);
    not  u_ne1 (not_eq1, n11);
    and  u_ge2 (n12, not_eq0, not_eq1);

    // ---- 4-bit magnitude comparator: cnt < duty ----
    // built bitwise from MSB down (standard subtractor-style comparator)
    wire lt3, eq3, lt2, eq2, lt1, eq1_, lt0;
    wire nD3, nD2, nD1, nD0;

    not  u_nd3 (nD3, D3);
    not  u_nd2 (nD2, D2);
    not  u_nd1 (nD1, D1);
    not  u_nd0 (nD0, D0);

    // bit3: lt3 = ~n4 & D3 ; eq3 = ~(n4 ^ D3)
    wire xn3;
    and  u_lt3 (lt3, not_n4, D3);
    xor  u_xn3 (xn3, n4, D3);
    not  u_eq3 (eq3, xn3);

    // bit2: lt2 = ~n3 & D2 ; eq2 = ~(n3 ^ D2)
    wire xn2, lt2raw;
    and  u_lt2 (lt2raw, not_n3, D2);
    xor  u_xn2 (xn2, n3, D2);
    not  u_eq2 (eq2, xn2);
    or   u_lt2c (lt2, lt3, w_lt2and);
    wire w_lt2and;
    and  u_lt2and (w_lt2and, eq3, lt2raw);

    // bit1: lt1 = ~n2 & D1 ; eq1_ = ~(n2 ^ D1)
    wire xn1, lt1raw, eqchain2, w_lt1and;
    and  u_lt1 (lt1raw, not_n2, D1);
    xor  u_xn1 (xn1, n2, D1);
    not  u_eq1raw (eq1_, xn1);
    and  u_eqc2 (eqchain2, eq3, eq2);
    and  u_lt1and (w_lt1and, eqchain2, lt1raw);
    or   u_lt1c (lt1, lt2, w_lt1and);

    // bit0: lt0 = ~n1 & D0 ; final n2_lt = cnt < duty
    wire xn0, lt0raw, eqchain3, w_lt0and, cnt_lt_duty;
    and  u_lt0 (lt0raw, not_n1, D0);
    xor  u_xn0 (xn0, n1, D0);
    and  u_eqc3 (eqchain3, eqchain2, eq1_);
    and  u_lt0and (w_lt0and, eqchain3, lt0raw);
    or   u_ltfinal (cnt_lt_duty, lt1, w_lt0and);

    // ---- stateA (hi-side window candidate) = guard_ge2 & cnt_lt_duty ----
    wire n30;
    and  u_stateA (n30, n12, cnt_lt_duty);

    // ---- comparator: cnt >= duty + 2 ----
    // implemented as NOT( cnt < duty+2 ), reuse subtractor-style chain on (duty+2)
    wire dp0, dp1, dp2, dp3, carry_in;
    // duty+2 addition (duty + 010b)
    xor  u_dp0 (dp0, D0, 1'b0);
    wire c_a0;
    and  u_ca0 (c_a0, D0, 1'b0);
    xor  u_dp1 (dp1, D1, 1'b1);
    wire c_a1, t_a1;
    and  u_ta1 (t_a1, D1, 1'b1);
    or   u_ca1 (c_a1, t_a1, c_a0);
    xor  u_dp2t (dp2t, D2, c_a1);
    wire dp2t, c_a2;
    and  u_ca2 (c_a2, D2, c_a1);
    xor  u_dp3t (dp3t, D3, c_a2);
    wire dp3t;

    // cnt < (duty+2) chain, mirroring the structure above using dp0..dp3t
    wire ndp3, ndp2, ndp1, ndp0;
    not  u_ndp3 (ndp3, dp3t);
    not  u_ndp2 (ndp2, dp2t);
    not  u_ndp1 (ndp1, dp1);
    not  u_ndp0 (ndp0, dp0);

    wire lt3b, eq3b, lt2rawb, w_lt2andb, lt2b, eq2b;
    wire xn3b, xn2b;
    and  u_lt3b (lt3b, not_n4, dp3t);
    xor  u_xn3b (xn3b, n4, dp3t);
    not  u_eq3b (eq3b, xn3b);

    and  u_lt2rawb (lt2rawb, not_n3, dp2t);
    xor  u_xn2b (xn2b, n3, dp2t);
    not  u_eq2b (eq2b, xn2b);
    and  u_lt2andb (w_lt2andb, eq3b, lt2rawb);
    or   u_lt2cb (lt2b, lt3b, w_lt2andb);

    wire xn1b, lt1rawb, eqchain2b, w_lt1andb, lt1b, eq1b;
    and  u_lt1rawb (lt1rawb, not_n2, dp1);
    xor  u_xn1b (xn1b, n2, dp1);
    not  u_eq1b (eq1b, xn1b);
    and  u_eqc2b (eqchain2b, eq3b, eq2b);
    and  u_lt1andb (w_lt1andb, eqchain2b, lt1rawb);
    or   u_lt1cb (lt1b, lt2b, w_lt1andb);

    wire xn0b, lt0rawb, eqchain3b, w_lt0andb, cnt_lt_dutyplus2;
    and  u_lt0rawb (lt0rawb, not_n1, dp0);
    xor  u_xn0b (xn0b, n1, dp0);
    and  u_eqc3b (eqchain3b, eqchain2b, eq1b);
    and  u_lt0andb (w_lt0andb, eqchain3b, lt0rawb);
    or   u_ltfinalb (cnt_lt_dutyplus2, lt1b, w_lt0andb);

    wire n31;
    not  u_stateBpre (n31, cnt_lt_dutyplus2);

    // ---- final output next-state, registered ----
    DFF dff_ph (.D(n30), .CLK(CLK), .RST(RST), .Q(PH));
    DFF dff_pl (.D(n31), .CLK(CLK), .RST(RST), .Q(PL));

endmodule

// Placeholder starting point -- NOT a complete recovered design.
// This is a naive pass-through implementation provided only so the
// toolchain and port list can be verified to compile and simulate.
// Replace this file with your reverse-engineered design.

module pwm_deadtime_gen (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,
    input  wire [3:0] duty,
    output reg        pwm_hi,
    output reg        pwm_lo
);

    reg [3:0] cnt;

    always @(posedge clk) begin
        if (rst) begin
            cnt <= 4'd0;
        end else if (en) begin
            cnt <= cnt + 4'd1;
        end else begin
            cnt <= cnt;
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            pwm_hi <= 1'b0;
            pwm_lo <= 1'b0;
        end else begin
            pwm_hi <= (cnt < duty);
            pwm_lo <= ~(cnt < duty);
        end
    end

endmodule
